import { formatMoney, type Money } from '../../shared/money';
import { PaymentDeclinedError } from '../errors';

export enum PaymentMethod {
  CARD = 'CARD',
  UPI = 'UPI',
  COD = 'COD',
}

export interface PaymentRequest {
  readonly orderId: string;
  readonly amount: Money;
  /** Generated by the shop so a retried charge can be deduplicated by the gateway. */
  readonly reference: string;
}

export interface PaymentReceipt {
  readonly method: PaymentMethod;
  readonly reference: string;
  readonly amount: Money;
  /** False for cash on delivery: the payment is secured now and collected at the door. */
  readonly capturedNow: boolean;
}

/** Strategy: how an order is paid for. Throws PaymentDeclinedError instead of returning a failure flag. */
export interface PaymentStrategy {
  readonly method: PaymentMethod;
  pay(request: PaymentRequest): PaymentReceipt;
}

/** Stand-in for a card gateway; `approve` decides, so tests can force a decline. */
export class FakeCardPayment implements PaymentStrategy {
  readonly method = PaymentMethod.CARD;

  constructor(
    private readonly last4: string,
    private readonly approve: (amount: Money) => boolean = () => true,
  ) {}

  pay(request: PaymentRequest): PaymentReceipt {
    if (!this.approve(request.amount)) throw new PaymentDeclinedError(this.method, `card ending ${this.last4} refused`);
    return { method: this.method, reference: request.reference, amount: request.amount, capturedNow: true };
  }
}

export class UpiPayment implements PaymentStrategy {
  readonly method = PaymentMethod.UPI;

  constructor(private readonly vpa: string) {}

  pay(request: PaymentRequest): PaymentReceipt {
    if (!/^[\w.-]+@[\w]+$/.test(this.vpa)) throw new PaymentDeclinedError(this.method, `invalid UPI id ${this.vpa}`);
    return { method: this.method, reference: request.reference, amount: request.amount, capturedNow: true };
  }
}

/** Shops cap COD because unpaid returns cost them money. */
export class CashOnDelivery implements PaymentStrategy {
  readonly method = PaymentMethod.COD;

  constructor(private readonly limit: Money = 500_000) {}

  pay(request: PaymentRequest): PaymentReceipt {
    if (request.amount > this.limit) throw new PaymentDeclinedError(this.method, `orders above ${formatMoney(this.limit)} need prepayment`);
    return { method: this.method, reference: request.reference, amount: request.amount, capturedNow: false };
  }
}
